"""Native operator context is generated by the server, never the queued row."""
from uuid import uuid4

import pytest

from app import inbox_runtime as runtime
from app import legacy_admin_identity as identity


class Database:
    def __init__(self):
        self.calls = []

    async def execute(self, query, params):
        self.calls.append((str(query), params))
        return self

    def scalar_one(self):
        return 7


@pytest.mark.parametrize('mode', ['enabled', 'disabled', 'invalid'])
async def test_operator_version_sets_current_local_context_before_database_guard(monkeypatch, mode):
    def configured():
        if mode == 'invalid':
            raise ValueError('invalid server configuration')
        return 'a' * 64 if mode == 'enabled' else None

    monkeypatch.setattr(identity, 'configured_digest', configured)
    db = Database()
    tenant, account = uuid4(), uuid4()
    assert await runtime.operator_version(db, tenant, account) == 7
    assert len(db.calls) == 2
    query, params = db.calls[0]
    assert "set_config('app.legacy_admin_digest',:digest,true)" in query
    assert params == {'digest': 'a' * 64 if mode == 'enabled' else ''}
    assert db.calls[1] == ('SELECT public.inbox_operator_version(:t,:a)', {'t': tenant, 'a': account})


async def test_disabled_native_context_clears_prior_value_in_same_transaction(monkeypatch):
    values = iter(['a' * 64, None])
    monkeypatch.setattr(identity, 'configured_digest', lambda: next(values))
    db = Database()
    tenant, account = uuid4(), uuid4()
    await runtime.operator_version(db, tenant, account)
    await runtime.operator_version(db, tenant, account)
    assert [params['digest'] for query, params in db.calls if 'set_config' in query] == ['a' * 64, '']
